describe('Tab Navigation with URL Hash Update', () => {
    beforeEach(() => {
        cy.visit('/your-page-url'); // Replace with the actual page URL
    });

    it('should update the URL hash when the first tab is clicked', () => {
        cy.get('[data-testid="tab-1"]').click();
        cy.url().should('include', '#tab1');
    });

    it('should update the URL hash when the second tab is clicked', () => {
        cy.get('[data-testid="tab-2"]').click();
        cy.url().should('include', '#tab2');
    });

    it('should not change the URL hash if the same tab is clicked again', () => {
        cy.get('[data-testid="tab-1"]').click();
        cy.url().should('include', '#tab1');
        cy.get('[data-testid="tab-1"]').click();
        cy.url().should('include', '#tab1'); // URL should remain the same
    });
});
